<script lang="ts">
 import {recordingToWav} from '$lib/assistant/audio';
 import FeedbackControls from './feedback-controls.svelte';
 import SpendingComparison from './spending-comparison.svelte';
 import {getContext,onDestroy} from 'svelte';
 import {AUTH_UI_CONTEXT,type AuthUiState} from '$lib/i18n/auth';
 import {PRIVACY_CONTEXT,type PrivacyState,concealed} from '$lib/privacy';
 import {formatExactAmount} from '$lib/ux/amount';
 import {formatDate} from '$lib/dates';
 import * as Card from '$lib/components/ui/card';
 import {Button} from '$lib/components/ui/button';
 import {Input} from '$lib/components/ui/input';
 import {Textarea} from '$lib/components/ui/textarea';
 import {Checkbox} from '$lib/components/ui/checkbox';
 import ChoiceSelect from '$lib/components/forms/choice-select.svelte';
 import AmountInput from '$lib/components/forms/amount-input.svelte';
 import DatePicker from '$lib/components/forms/date-picker.svelte';
 import LoadingScope from '$lib/components/shared/loading-scope.svelte';
 import ScrollRegion from '$lib/components/shared/scroll-region.svelte';
 import Disclosure from '$lib/components/shared/disclosure.svelte';
 let {workspaceId,baseRunId='',currency='IDR',accounts=[],events=[],externalEnabled=false,voiceEnabled=false,enabled=true,consentVersion=0,providerName='Groq',voiceInputFormat='native'}:{providerName?:string;voiceInputFormat?:'native'|'wav';workspaceId:string;baseRunId?:string;currency?:string;accounts?:{id:string;name:string}[];events?:{id:string;date:string;kind:string;description:string;amount:string}[];externalEnabled?:boolean;voiceEnabled?:boolean;enabled?:boolean;consentVersion?:number}=$props();
 const ui=getContext<AuthUiState>(AUTH_UI_CONTEXT),privacy=getContext<PrivacyState>(PRIVACY_CONTEXT);
 const L=(en:string,id:string)=>ui.locale==='id'?id:en;
 const money=(value:unknown)=>value==null?'—':`${currency} ${concealed(formatExactAmount(String(value),ui.locale),privacy.hidden)}`;
 let comparisonEvidence=$state<Record<string,any>>({}),customerEvidence=$state<Record<string,any>>({});
 let evidence=$state<Record<string,any[]>>({}),conversationList=$state<any[]>([]);
 let dimension=$state('category');
 let tab=$state('insights'),busy=$state(false),error=$state(''),notice=$state(''),analytics=$state<any>(null),scenarios=$state<any[]>([]),scenario=$state<any>(null),summary=$state<any>(null),plan=$state<any>(null),draft=$state<any>(null),chat=$state<any[]>([]),question=$state(''),entryText=$state(''),conversation=$state('');
 let scenarioName=$state(''),scenarioKind=$state('purchase'),purchaseAmount=$state(''),purchaseDate=$state(''),purchaseAccount=$state(''),eventId=$state(''),delay=$state('14');
 let cadence=$state('weekly'),nudges=$state('off'),scheduleEnabled=$state(false),sendTime=$state('09:00'),quietStart=$state('21:00'),quietEnd=$state('08:00'),email=$state(false);
 let pendingRecording=$state(false),recording=$state(false),recorder:MediaRecorder|null=null,stream:MediaStream|null=null,recordTimer:ReturnType<typeof setTimeout>|undefined,aborted=false,disposed=false,recordGeneration=0,controllers=new Set<AbortController>(),lastScope='';
 let entryOrigin=$state<'text'|'voice'>('text');
 let entryKey=cryptoSafe(),chatKey=cryptoSafe();function cryptoSafe(){return globalThis.crypto?.randomUUID?.()??'';}
 $effect(()=>{const scope=workspaceId+':'+consentVersion+':'+enabled+':'+externalEnabled+':'+voiceEnabled+':'+providerName+':'+voiceInputFormat;if(lastScope!==scope){lastScope=scope;for(const c of controllers)c.abort();controllers.clear();stopRecording(true);analytics=null;evidence={};comparisonEvidence={};customerEvidence={};conversationList=[];scenarios=[];scenario=null;summary=null;plan=null;draft=null;chat=[];conversation='';question='';entryText='';entryOrigin='text';error='';notice='';busy=false;}});
 onDestroy(()=>{disposed=true;for(const c of controllers)c.abort();stopRecording(true);});
 async function api(path:string,method='GET',body?:unknown){const ws=workspaceId,scope=lastScope,c=new AbortController();controllers.add(c);try{const r=await fetch(`/api/workspaces/${ws}/assistant/v2/${path}`,{method,signal:c.signal,headers:body===undefined?{}:{'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const result=await r.json();if(c.signal.aborted||scope!==lastScope||ws!==workspaceId||disposed)throw new DOMException('Workspace changed','AbortError');if(!r.ok)throw new Error(result.message??L('This request could not be completed.','Permintaan belum dapat diselesaikan.'));return result;}finally{controllers.delete(c);}}
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';const scope=lastScope;try{await action();}catch(e){if(scope===lastScope&&(e as Error).name!=='AbortError')error=(e as Error).message;}finally{if(scope===lastScope)busy=false;}}
 async function load(){await run(async()=>{if(tab==='insights'){analytics=await api('analytics?groupBy='+dimension);comparisonEvidence={};customerEvidence={};}if(tab==='scenarios')scenarios=(await api('scenarios')).items;if(tab==='summaries'){summary=await api('summaries');const s=summary.schedule;if(s){cadence=s.cadence;nudges=s.nudge_frequency;scheduleEnabled=s.enabled;sendTime=s.local_send_time.slice(0,5);quietStart=s.quiet_start.slice(0,5);quietEnd=s.quiet_end.slice(0,5);email=s.channels.includes('email');}}});}
 async function createScenario(){await run(async()=>{const overrides=scenarioKind==='purchase'?[{kind:'purchase',accountId:purchaseAccount,date:purchaseDate,amount:purchaseAmount}]:scenarioKind==='delay_invoice'?[{kind:scenarioKind,eventId,days:Number(delay)}]:[{kind:scenarioKind,eventId,amount:purchaseAmount}];scenario=await api('scenarios','POST',{baseRunId,name:scenarioName,overrides});scenarios=(await api('scenarios')).items;});}
 async function ask(){if(!question.trim())return;const text=question;await run(async()=>{const answer=await api('chat','POST',{text,locale:ui.locale,conversationId:conversation||null,requestKey:chatKey});conversation=answer.conversationId;chat=[...chat,{text,...answer}];question='';chatKey=cryptoSafe();});}
 async function openConversation(id:string){await run(async()=>{const messages=(await api(`conversations/${id}`)).items;conversation=id;chat=messages.filter((m:any)=>m.role==='assistant').map((m:any)=>({...JSON.parse(m.content),text:messages.find((u:any)=>u.role==='user'&&u.request_key===m.request_key)?.content??''}));});}
 async function parseEntry(){if(!entryText.trim())return;await run(async()=>{draft=await api('entry','POST',{text:entryText,origin:entryOrigin,locale:ui.locale,requestKey:entryKey});});}
 async function confirmEntry(){await run(async()=>{const saved=await api(`entry/${draft.id}/confirm`,'POST',{confirmation:'CREATE_TRANSACTION',version:draft.version,fields:draft.fields});notice=L('Transaction saved.','Transaksi tersimpan.');draft=null;entryText='';entryOrigin='text';entryKey=cryptoSafe();});}
 async function record(){if(!voiceEnabled||!externalEnabled||busy||recording||pendingRecording)return;pendingRecording=true;error='';const scope=lastScope,generation=++recordGeneration;try{const activeStream=await navigator.mediaDevices.getUserMedia({audio:true});if(scope!==lastScope||disposed||generation!==recordGeneration){activeStream.getTracks().forEach(t=>t.stop());return;}stream=activeStream;const mime=['audio/webm','audio/ogg','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw new Error(L('Voice recording is unavailable. Use text entry.','Rekaman tidak tersedia. Gunakan teks.'));recorder=new MediaRecorder(stream,{mimeType:mime});const chunks:Blob[]=[];let bytes=0;aborted=false;recorder.ondataavailable=e=>{if(generation!==recordGeneration||disposed||scope!==lastScope)return;bytes+=e.data.size;if(bytes>2000000){stopRecording(true);error=L('Recording is too large. Try a shorter message.','Rekaman terlalu besar. Coba pesan lebih singkat.');}else chunks.push(e.data);};recorder.onstop=()=>{activeStream.getTracks().forEach(t=>t.stop());if(stream===activeStream)stream=null;if(generation!==recordGeneration)return;recording=false;if(aborted||scope!==lastScope||disposed)return;const ws=workspaceId;void run(async()=>{const c=new AbortController();controllers.add(c);try{const recordingBlob=new Blob(chunks,{type:mime});const audio=voiceInputFormat==='wav'?await recordingToWav(recordingBlob):recordingBlob;if(c.signal.aborted||scope!==lastScope||disposed||generation!==recordGeneration)return;const r=await fetch(`/api/workspaces/${ws}/assistant/v2/voice`,{method:'POST',signal:c.signal,headers:{'content-type':audio.type,'idempotency-key':cryptoSafe()},body:audio});const result=await r.json();if(ws!==workspaceId)return;if(!r.ok)throw new Error(result.message);if(c.signal.aborted||scope!==lastScope||disposed)return;entryText=result.transcript;entryOrigin='voice';entryKey=cryptoSafe();notice=L('Review the transcript, then create a draft.','Tinjau transkrip, lalu buat draf.');}finally{controllers.delete(c);chunks.length=0;}});};recorder.start(250);recording=true;recordTimer=setTimeout(()=>stopRecording(false),30000);}catch(e){stream?.getTracks().forEach(t=>t.stop());stream=null;error=L('Microphone recording could not start. You can still type your transaction.','Mikrofon belum dapat dimulai. Kamu tetap dapat mengetik transaksi.');}finally{if(generation===recordGeneration)pendingRecording=false;}}
 function stopRecording(cancel:boolean){aborted=cancel;if(cancel){recordGeneration++;pendingRecording=false;}if(recordTimer)clearTimeout(recordTimer);if(recorder?.state==='recording')recorder.stop();else stream?.getTracks().forEach(t=>t.stop());if(cancel)recording=false;}
 async function feedback(sourceType:'finding'|'summary',item:any,action:'helpful'|'not_helpful'|'dismiss'){
  await api(`feedback/${sourceType}/${item.id}`,'POST',{action});
  if(action==='dismiss'){if(sourceType==='finding')analytics={...analytics,findings:analytics.findings.filter((f:any)=>f.id!==item.id),goals:analytics.goals.filter((g:any)=>g.feedbackTarget?.id!==item.id),savingsOpportunity:analytics.savingsOpportunity?.feedbackTarget?.id===item.id?null:analytics.savingsOpportunity};else summary={...summary,items:summary.items.filter((s:any)=>s.id!==item.id)};}
  else {item.feedback=action;if(sourceType==='finding')analytics={...analytics,findings:[...analytics.findings]};else summary={...summary,items:[...summary.items]};}
 }
 async function saveSchedule(){await run(async()=>{await api('summary-schedule','PUT',{version:summary?.schedule?.version??0,enabled:scheduleEnabled,cadence,nudgeFrequency:nudges,channels:email?['in_app','email']:['in_app'],sendTime,quietStart,quietEnd});summary=await api('summaries');notice=L('Check-in preferences saved.','Preferensi ringkasan tersimpan.');});}
 function label(status:string){const labels:Record<string,string>={unknown:L('More history needed','Perlu riwayat lagi'),often_late:L('Often paid after the due date','Sering dibayar setelah jatuh tempo'),sometimes_late:L('Sometimes paid late','Kadang dibayar terlambat'),usually_on_time:L('Usually paid on time','Biasanya dibayar tepat waktu'),not_burning_cash:L('Not currently burning cash','Kas saat ini tidak berkurang'),incomplete_scope:L('More coverage needed','Perlu cakupan lebih lengkap'),no_available_cash:L('No available cash','Tidak ada kas tersedia'),burning_cash:L('Cash decreasing at this pace','Kas berkurang pada laju ini'),possible_duplicate:L('Possible duplicate','Kemungkinan duplikat'),unusual_spending:L('Unusual purchase','Pembelian tidak biasa'),legitimate:L('Marked as intentional','Ditandai disengaja'),dismissed:L('Dismissed','Diabaikan'),subscription_overlap:L('Overlapping subscriptions','Langganan tumpang tindih'),subscription_charge_increase:L('Subscription charge changed','Tagihan langganan berubah'),budget_overspend:L('Spending above the budget','Pengeluaran di atas anggaran'),active:L('Ready for review','Siap ditinjau'),achieved:L('Goal reached','Tujuan tercapai'),no_deadline:L('Choose a target date','Pilih tanggal target'),overdue:L('Review the target date','Tinjau tanggal target')};return labels[status]??status.replaceAll('_',' ');}
</script>
<LoadingScope active={busy}/>
<Card.Root class="v2-panel"><Card.Header><Card.Title>{L('A little more clarity with Capy','Lebih jelas bersama Capy')}</Card.Title><Card.Description>{L('Explore your cashflow, review patterns, and plan your next step. Every amount is calculated from your records.','Jelajahi arus kas, tinjau pola, dan rencanakan langkah selanjutnya. Setiap jumlah dihitung dari catatanmu.')}</Card.Description></Card.Header><Card.Content>
 <div class="tabs" aria-label={L('Assistant features','Fitur asisten')}>{#each [{value:'insights',label:L('Insights','Wawasan')},{value:'scenarios',label:L('What if?','Bagaimana jika?')},{value:'payments',label:L('Payment plan','Rencana pembayaran')},{value:'chat',label:L('Ask Capy','Tanya Capy')},{value:'entry',label:L('Text & voice entry','Entri teks & suara')},{value:'summaries',label:L('Check-ins','Ringkasan')}] as item}<Button variant={tab===item.value?'default':'outline'} aria-pressed={tab===item.value} onclick={()=>{tab=item.value;error='';}}>{item.label}</Button>{/each}</div>
 {#if error}<p role="alert" class="error">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if !enabled&&!['chat','entry'].includes(tab)}<p>{L('Enable local forecasts in the settings below to use these features.','Aktifkan proyeksi lokal di pengaturan di bawah untuk menggunakan fitur ini.')}</p>
 {:else if tab==='insights'}
 <div class="section-heading"><h3>{L('Patterns worth a look','Pola yang layak ditinjau')}</h3><label>{L('Group spending by','Kelompokkan pengeluaran berdasarkan')}<ChoiceSelect bind:value={dimension} items={[{value:'category',label:L('Category','Kategori')},{value:'merchant',label:L('Merchant','Penjual')},{value:'account',label:L('Account','Akun')}]}/></label><Button variant="outline" onclick={load} disabled={busy}>{L('Refresh insights','Perbarui wawasan')}</Button></div>
 {#if analytics}<p class="muted">{L('As of','Per')} {formatDate(analytics.asOfDate)} · {L('Selected accounts and one currency','Akun terpilih dan satu mata uang')}</p>
 {#if analytics.coverage.length}<p class="muted">{L('Some data is missing or excluded. Forecast-based suggestions may be unavailable.','Beberapa data tidak lengkap atau dikecualikan. Saran berbasis proyeksi mungkin belum tersedia.')}</p>{/if}
 {#if analytics.comparison}<h4>{L('Spending this month vs last month','Pengeluaran bulan ini vs bulan lalu')}</h4><p class="muted">{formatDate(analytics.comparison.period.currentStart)} – {formatDate(analytics.comparison.period.currentEnd)} / {formatDate(analytics.comparison.period.previousStart)} – {formatDate(analytics.comparison.period.previousEnd)} · {L('Equal elapsed days; refunds recorded as income are separate.','Jumlah hari sama; pengembalian yang dicatat sebagai pemasukan terpisah.')}</p><SpendingComparison items={analytics.comparison.items}/><ScrollRegion label={L('Assistant data table','Tabel data asisten')}><table><thead><tr><th>{L('Group','Kelompok')}</th><th>{L('This month','Bulan ini')}</th><th>{L('Last month','Bulan lalu')}</th><th>{L('Change','Perubahan')}</th><th>{L('Sources','Sumber')}</th></tr></thead><tbody>{#each analytics.comparison.items as item}<tr><th>{item.categoryName}</th><td>{money(item.current)}</td><td>{money(item.previous)}</td><td>{money(item.change)} {item.percentageChange===null?'':privacy.hidden?'•••':`(${formatExactAmount(item.percentageChange,ui.locale)}%)`}</td><td><Button variant="outline" size="sm" disabled={busy||privacy.hidden} onclick={()=>run(async()=>{comparisonEvidence={...comparisonEvidence,[item.groupKey]:await api('comparison-evidence?groupBy='+analytics.comparison.dimension+'&groupKey='+encodeURIComponent(item.groupKey))};})}>{L('See records','Lihat catatan')}</Button></td></tr>{/each}</tbody></table></ScrollRegion>{#if !privacy.hidden}{#each analytics.comparison.items as item}{#if comparisonEvidence[item.groupKey]}<Disclosure>{#snippet title()}{item.categoryName} · {L('Source records','Catatan sumber')}{/snippet}<p class="muted">{L('Amounts for category comparisons are the allocated portions of each transaction.','Jumlah pada perbandingan kategori adalah bagian transaksi yang dialokasikan.')}</p><ul>{#each comparisonEvidence[item.groupKey].items as record}<li>{formatDate(record.date)} · {record.accountName} · {record.categoryName} · {money(record.amount)} · {record.period==='current'?L('This month','Bulan ini'):L('Last month','Bulan lalu')}</li>{/each}</ul>{#if comparisonEvidence[item.groupKey].truncated}<p class="muted">{L('Showing the latest 50 source records; totals include the full comparison.','Menampilkan 50 catatan sumber terbaru; total mencakup seluruh perbandingan.')}</p>{/if}<Button variant="link" href="/transactions">{L('Review transactions','Tinjau transaksi')}</Button></Disclosure>{/if}{/each}{/if}{#if !analytics.comparison.items.length}<p>{L('No expenses in these periods yet.','Belum ada pengeluaran pada periode ini.')}</p>{/if}{/if}
 <h4>{L('Review unusual or repeated charges','Tinjau transaksi tidak biasa atau berulang')}</h4><div class="item-list">{#each analytics.findings as finding}<article><h5>{finding.facts.name?`${finding.facts.name} · `:''}{label(finding.kind)} · {label(finding.state)}</h5><p>{money(finding.facts.amount)}{finding.facts.median?` · ${L('Usual median','Median biasanya')} ${money(finding.facts.median)}`:''}</p><p class="muted">{L('A larger or repeated purchase can be intentional. Review the records before correcting anything.','Pembelian besar atau berulang bisa disengaja. Tinjau catatan sebelum mengubahnya.')}</p><div class="actions"><Button variant="outline" size="sm" onclick={()=>run(async()=>{evidence={...evidence,[finding.id]:(await api(`findings/${finding.id}/evidence`)).items};})}>{L('See why','Lihat alasannya')}</Button><Button variant="outline" size="sm" href={finding.kind.startsWith('subscription')?'/subscriptions':finding.kind==='budget_overspend'?'/budgets':'/transactions'}>{L('Review source records','Tinjau catatan sumber')}</Button>{#if finding.state==='active'}<Button variant="outline" size="sm" onclick={()=>run(async()=>{await api(`findings/${finding.id}`,'PATCH',{state:'legitimate'});analytics=await api('analytics');})}>{L('Intentional','Disengaja')}</Button>{/if}</div>{#if evidence[finding.id]}{#if finding.kind==='possible_duplicate'}<p class="muted">{L('Matching records','Catatan yang cocok')}: {finding.facts.matchingRecordCount??2} · {L('Same account, merchant, amount and calendar date. Separate purchases can still match; no bank reference or purchase time is checked.','Akun, merchant, jumlah, dan tanggal yang sama. Pembelian terpisah tetap bisa cocok; referensi bank dan waktu pembelian tidak diperiksa.')}</p>{:else if finding.kind==='unusual_spending'&&finding.facts.threshold}<p class="muted">{L('Compared with earlier purchases in this category and account','Dibandingkan dengan pembelian sebelumnya pada kategori dan akun ini')}: {finding.facts.sampleSize} {L('records across','catatan dalam')} {finding.facts.historyDays} {L('different dates','tanggal berbeda')} ({formatDate(finding.facts.baselineStart)} – {formatDate(finding.facts.baselineEnd)}).</p><p>{L('Usual median','Median biasanya')}: {money(finding.facts.median)} · {L('Review threshold','Ambang peninjauan')}: {money(finding.facts.threshold)}</p><p class="muted">{L('The threshold considers both your usual spending and how much it varies. This purchase may still be intentional.','Ambang ini mempertimbangkan pengeluaran biasanya dan variasinya. Pembelian ini tetap mungkin disengaja.')}</p>{/if}{#if finding.facts.evidenceTruncated}<p class="muted">{L('Showing up to 50 source records.','Menampilkan hingga 50 catatan sumber.')}</p>{/if}<ul>{#each evidence[finding.id] as source}<li>{formatDate(source.date)} · {source.label} · {source.accountName} · {money(source.amount)}</li>{/each}</ul>{/if}<FeedbackControls value={finding.feedback} disabled={busy} onsubmit={(action)=>feedback('finding',finding,action)}/></article>{/each}</div>{#if !analytics.findings.length}<p>{L('Nothing unusual to review in the available history.','Tidak ada transaksi tidak biasa untuk ditinjau pada riwayat yang tersedia.')}</p>{/if}
 {#if analytics.burn}<p class="muted">{formatDate(analytics.burn.windowStart)} – {formatDate(analytics.burn.windowEnd)}</p><h4>{L('Business runway','Ketahanan kas bisnis')}</h4><p>{label(analytics.burn.status)}</p><div class="metrics"><div><small>{L('Gross monthly spending','Pengeluaran bulanan bruto')}</small><strong>{money(analytics.burn.grossMonthlyBurn)}</strong></div><div><small>{L('Net monthly burn','Pengurangan kas bulanan neto')}</small><strong>{money(analytics.burn.netMonthlyBurn)}</strong></div><div><small>{L('Estimated runway','Estimasi ketahanan kas')}</small><strong>{analytics.burn.runwayMonths===null?'—':`${privacy.hidden?'•••':formatExactAmount(analytics.burn.runwayMonths,ui.locale)} ${L('months','bulan')}`}</strong></div></div><p class="muted">{L('90-day operating history, using 30 days per month. Transfers, opening funds and marked one-offs are excluded. This is an estimate, not a guarantee.','Riwayat operasi 90 hari, menggunakan 30 hari per bulan. Transfer, saldo awal, dan transaksi sekali saja yang ditandai dikecualikan. Ini estimasi, bukan jaminan.')}</p><p>{L('Unrestricted cash','Kas tanpa cadangan')}: {money(analytics.burn.unrestrictedCash)}</p><Disclosure>{#snippet title()}{L('Compare with the cashflow forecast','Bandingkan dengan proyeksi arus kas')}{/snippet}<p>{analytics.burn.forecast.horizonDays} {L('days from','hari dari')} {formatDate(analytics.asOfDate)}</p><p>{L('Lowest projected cash','Kas proyeksi terendah')}: {money(analytics.burn.forecast.minimumBalance)} · {L('First shortfall','Kekurangan pertama')}: {formatDate(analytics.burn.forecast.firstShortfallDate,'—')}</p><p>{L('Safe to spend','Aman dibelanjakan')}: {money(analytics.burn.forecast.safeToSpend)}</p><p class="muted">{L('Runway uses historical operating cash. The forecast also includes permitted upcoming obligations; the two estimates can differ.','Ketahanan kas memakai riwayat operasi. Proyeksi juga mencakup kewajiban mendatang yang diizinkan; kedua estimasi dapat berbeda.')}</p></Disclosure>{/if}
 {#if analytics.customers.length}<h4>{L('Customer payment history','Riwayat pembayaran pelanggan')}</h4><div class="item-list">{#each analytics.customers as c}<article><h5>{c.name} · {label(c.band)}</h5><p>{c.sampleSize} {L('settled invoices','faktur lunas')} · {c.overdueCount} {L('currently overdue','saat ini terlambat')} · {money(c.overdueAmount)}</p><p class="muted">{L('At least five settled invoices are needed for a pattern. This is not a credit score.','Minimal lima faktur lunas diperlukan untuk mengetahui pola. Ini bukan skor kredit.')}</p><p>{L('Median settled delay','Median keterlambatan pelunasan')}: {c.medianDaysLate??'—'} {L('days','hari')}</p><Button variant="outline" size="sm" disabled={busy||privacy.hidden} onclick={()=>run(async()=>{customerEvidence={...customerEvidence,[c.customerId]:await api('customers/'+c.customerId+'/evidence')};})}>{L('See invoices','Lihat faktur')}</Button>{#if customerEvidence[c.customerId]&&!privacy.hidden}<ul>{#each customerEvidence[c.customerId].items as invoice}<li><Button variant="link" size="sm" href={'/invoices/'+invoice.id}>{invoice.number}</Button> · {L('Due','Jatuh tempo')}: {formatDate(invoice.dueDate)} · {L('Unpaid','Belum dibayar')}: {money(invoice.outstanding)}{invoice.settledOn?` · ${L('Last payment','Pembayaran terakhir')}: ${formatDate(invoice.settledOn)}`:''}</li>{/each}</ul>{#if customerEvidence[c.customerId].truncated}<p class="muted">{L('Showing 50 invoices; the pattern includes the full permitted history.','Menampilkan 50 faktur; pola mencakup seluruh riwayat yang diizinkan.')}</p>{/if}{/if}</article>{/each}</div>{/if}
 <h4>{L('Savings goals, one week at a time','Tujuan tabungan, satu minggu tiap langkah')}</h4><div class="item-list">{#each analytics.goals as g}<article><h5>{g.name}</h5><p>{label(g.coaching.status)} · {L('Remaining','Sisa')} {money(g.coaching.remaining)}</p>{#if g.coaching.weeklyTarget}<p>{L('Weekly target','Target mingguan')}: {money(g.coaching.weeklyTarget)}</p><p class="muted">{g.coaching.affordable===true?L('Within the current safe-to-spend estimate. Review before contributing.','Dalam estimasi aman dibelanjakan saat ini. Tinjau sebelum menabung.'):L('Review available cash or adjust the goal timeline before contributing.','Tinjau kas yang tersedia atau sesuaikan target waktu sebelum menabung.')}</p>{/if}<Button variant="link" href="/goals">{L('Review goal','Tinjau tujuan')}</Button><FeedbackControls value={g.feedbackTarget?.feedback} disabled={busy} onsubmit={(action)=>feedback('finding',g.feedbackTarget,action)}/></article>{/each}</div>
 <h4>{L('Small opportunities to review','Peluang kecil untuk ditinjau')}</h4><p>{L('Review confirmed subscriptions for overlapping services or price changes. A charge does not tell us whether you use a service. Compare providers’ published prices, billing periods and cancellation terms before switching.','Tinjau langganan yang telah dikonfirmasi untuk layanan tumpang tindih atau perubahan harga. Transaksi tidak menunjukkan apakah layanan digunakan. Bandingkan harga resmi penyedia, periode tagihan, dan syarat pembatalan sebelum berganti.')}</p><div class="item-list">{#each analytics.subscriptions as s}<article><h5>{s.name}</h5><p>{money(s.amount)} · {formatDate(s.nextCharge)}</p><Button variant="link" href="/subscriptions">{L('Review subscription','Tinjau langganan')}</Button></article>{/each}</div>{#if analytics.savingsOpportunity}<p>{L('Maximum cash available to review for saving','Kas maksimum untuk dipertimbangkan ditabung')}: <strong>{money(analytics.savingsOpportunity.maximumAllocation)}</strong></p><FeedbackControls value={analytics.savingsOpportunity.feedbackTarget?.feedback} disabled={busy} onsubmit={(action)=>feedback('finding',analytics.savingsOpportunity.feedbackTarget,action)}/>{/if}
 {:else}<p class="muted">{L('Refresh to see comparisons, review prompts and goal targets from your permitted records.','Perbarui untuk melihat perbandingan, saran tinjauan, dan target tujuan dari catatan yang diizinkan.')}</p>{/if}
 {:else if tab==='scenarios'}
 <h3>{L('Try an idea before changing your plans','Coba ide sebelum mengubah rencana')}</h3><p class="muted">{L('Scenarios leave your real records unchanged. Refresh the base forecast above first.','Skenario tidak mengubah catatan asli. Perbarui proyeksi dasar di atas terlebih dahulu.')}</p><form onsubmit={e=>{e.preventDefault();void createScenario();}}><div class="form-grid"><label>{L('Scenario name','Nama skenario')}<Input bind:value={scenarioName} maxlength={100} required/></label><label>{L('Change','Perubahan')}<ChoiceSelect bind:value={scenarioKind} items={[{value:'purchase',label:L('One-off purchase','Pembelian sekali saja')},{value:'delay_invoice',label:L('Invoice arrives later','Faktur dibayar lebih lambat')},{value:'expense_amount',label:L('Change a planned expense','Ubah pengeluaran terencana')},{value:'recurring_amount',label:L('Change a recurring expense','Ubah pengeluaran berulang')}]}/></label>
 {#if scenarioKind==='purchase'}<label>{L('Account','Akun')}<ChoiceSelect bind:value={purchaseAccount} items={[{value:'',label:L('Select','Pilih')},...accounts.map(a=>({value:a.id,label:a.name}))]} required/></label><label>{L('Date','Tanggal')}<DatePicker bind:value={purchaseDate} required/></label>{:else}<label>{L('Forecast event','Peristiwa proyeksi')}<ChoiceSelect bind:value={eventId} items={[{value:'',label:L('Select','Pilih')},...events.filter(e=>scenarioKind==='delay_invoice'?e.kind==='invoice':scenarioKind==='recurring_amount'?e.kind==='recurring'&&e.amount.startsWith('-'):e.amount.startsWith('-')).map(e=>({value:e.id,label:`${e.description} · ${formatDate(e.date)}`}))]} required/></label>{/if}
 {#if scenarioKind==='delay_invoice'}<label>{L('Days later','Hari keterlambatan')}<Input type="number" min={1} max={90} bind:value={delay} required/></label>{:else}<label>{L('Amount','Jumlah')}<AmountInput bind:value={purchaseAmount} {currency} required/></label>{/if}</div><Button type="submit" disabled={busy||!baseRunId}>{L('Compare scenario','Bandingkan skenario')}</Button></form>
 {#if scenario}<h4>{L('Before and after','Sebelum dan sesudah')}</h4><ScrollRegion label={L('Assistant data table','Tabel data asisten')}><table><thead><tr><th>{L('Measure','Ukuran')}</th><th>{L('Base','Dasar')}</th><th>{L('Scenario','Skenario')}</th></tr></thead><tbody><tr><th>{L('Minimum cash','Kas minimum')}</th><td>{money(scenario.result.before.minimumBalance)}</td><td>{money(scenario.result.after.minimumBalance)}</td></tr><tr><th>{L('Safe to spend','Aman dibelanjakan')}</th><td>{money(scenario.result.before.safeToSpend)}</td><td>{money(scenario.result.after.safeToSpend)}</td></tr><tr><th>{L('First shortfall','Kekurangan pertama')}</th><td>{formatDate(scenario.result.before.firstShortfallDate,'—')}</td><td>{formatDate(scenario.result.after.firstShortfallDate,'—')}</td></tr></tbody></table></ScrollRegion><h4>{L('Changes in this scenario','Perubahan dalam skenario')}</h4><div class="item-list">{#each scenario.result.changedEvents as change}<article><h5>{change.after.description}</h5><p>{change.before?`${L('Before','Sebelum')}: ${formatDate(change.before.date)} · ${money(change.before.amount)}`:L('New hypothetical expense','Pengeluaran hipotetis baru')}</p><p>{L('After','Sesudah')}: {formatDate(change.after.date)} · {money(change.after.amount)}</p></article>{/each}</div>{/if}
 <Button variant="outline" onclick={load} disabled={busy}>{L('Saved scenarios','Skenario tersimpan')}</Button><div class="item-list">{#each scenarios as s}<article><h5>{s.name}</h5><p>{s.stale?L('Source data changed. Recreate this scenario from a fresh forecast.','Data sumber berubah. Buat ulang skenario dari proyeksi terbaru.'):L('Saved forecast comparison','Perbandingan proyeksi tersimpan')}</p><Button variant="outline" disabled={s.stale} onclick={()=>scenario={result:s.result}}>{L('View comparison','Lihat perbandingan')}</Button></article>{/each}</div>
 {:else if tab==='payments'}<h3>{L('A plan for the cash you have','Rencana untuk kas yang tersedia')}</h3><p class="muted">{L('Order obligations by due date, then review essential status and explicit terms. No money moves or dates change. Future income is not counted as available cash.','Urutkan kewajiban berdasarkan jatuh tempo, lalu tinjau kebutuhan esensial dan syarat yang disepakati. Tidak ada uang dipindahkan atau tanggal diubah. Pemasukan mendatang tidak dihitung sebagai kas tersedia.')}</p><Button onclick={()=>run(async()=>{plan=await api('payment-plan','POST',{terms:[]});})} disabled={busy}>{L('Review payment plan','Tinjau rencana pembayaran')}</Button>{#if plan}<div class="item-list">{#each plan.items as p}<article><h4>{p.name}</h4><p>{formatDate(p.dueDate)} · {money(p.amount)}</p><p>{L('Proposed payment date','Usulan tanggal pembayaran')}: {formatDate(p.proposedDate)}{p.latestPermittedDate?` · ${L('Agreed latest date','Tanggal terakhir disepakati')}: ${formatDate(p.latestPermittedDate)}`:''}</p><p>{L('Covered','Tercakup')}: {money(p.allocated)} · {L('Still to plan','Masih perlu direncanakan')}: {money(p.unpaid)}</p><div class="form-grid"><label class="check"><Checkbox bind:checked={p.essential}/>{L('Essential obligation','Kewajiban esensial')}</label><label>{L('Agreed minimum payment','Pembayaran minimum disepakati')}<AmountInput bind:value={p.minimumInput} {currency}/></label><label>{L('Agreed deferral days','Penundaan hari disepakati')}<Input type="number" min={0} max={90} bind:value={p.deferralInput}/></label></div><p class="muted">{L('Leave unknown terms empty. Ask the payee before relying on a deferral or minimum payment.','Biarkan kosong jika belum diketahui. Tanyakan kepada penerima sebelum mengandalkan penundaan atau pembayaran minimum.')}</p><Button variant="link" href={p.eventId.startsWith('payable:')?`/business/payables/${p.sourceId}`:'/bills'}>{L('Review original record','Tinjau catatan asli')}</Button></article>{/each}</div><Button variant="outline" onclick={()=>run(async()=>{plan=await api('payment-plan','POST',{terms:plan.items.map((p:any)=>({eventId:p.eventId,essential:p.essential,minimumPayment:p.minimumInput||null,deferralDays:p.deferralInput===''||p.deferralInput===undefined?null:Number(p.deferralInput)}))});})} disabled={busy}>{L('Recalculate with reviewed terms','Hitung ulang dengan syarat ditinjau')}</Button><p>{L('Total still to plan','Total masih perlu direncanakan')}: {money(plan.unpaid)}</p><p>{L('Minimum cash on this proposed schedule','Kas minimum pada usulan jadwal')}: {money(plan.simulation.minimumBalance)} · {L('First shortfall','Kekurangan pertama')}: {formatDate(plan.simulation.firstShortfallDate,'—')}</p>{/if}
 {:else if tab==='chat'}<p class="muted">{providerName}</p><h3>{L('Ask about your recorded money','Tanyakan tentang catatan uangmu')}</h3><p class="muted">{L('Try “How much did I spend on food last month?” or “Who owes me money?” The language provider chooses a read-only query; CapyBudget supplies the figures. Your question is sent to the configured provider, but retrieved financial records stay here.','Coba “Berapa pengeluaran makan bulan lalu?” atau “Siapa yang belum membayar?” Penyedia bahasa memilih kueri baca saja; CapyBudget menghitung angka. Pertanyaanmu dikirim ke penyedia yang dikonfigurasi, tetapi catatan keuangan hasil pencarian tetap di sini.')}</p>
 <Button variant="outline" disabled={!externalEnabled||busy} onclick={()=>run(async()=>{conversationList=(await api('conversations')).items;})}>{L('Previous conversations','Percakapan sebelumnya')}</Button>{#if conversationList.length}<div class="actions">{#each conversationList as item}<Button variant="outline" onclick={()=>openConversation(item.id)}>{privacy.hidden?'•••':item.title}</Button>{/each}</div>{/if}
 {#if !externalEnabled}<p>{L('Opt in to external language processing below to ask questions. Local forecasts do not need an external provider.','Izinkan pemrosesan bahasa eksternal di bawah untuk bertanya. Proyeksi lokal tidak memerlukan penyedia eksternal.')}</p>{/if}<div class="item-list" aria-live="polite">{#each chat as c}<article><h4>{privacy.hidden?'•••':c.text}</h4><p>{c.message}</p>{#if c.asOfDate}<p class="muted">{L('Based on records as of','Berdasarkan catatan per')} {formatDate(c.asOfDate)}</p>{/if}{#if c.proposal?.kind==='review_transaction_entry'}<Button variant="outline" onclick={()=>{entryOrigin='text';entryText=c.proposal.text;entryKey=cryptoSafe();tab='entry';}}>{L('Review a transaction draft','Tinjau draf transaksi')}</Button>{/if}{#if c.facts&&!privacy.hidden}{#if c.tool==='spending'}<p><strong>{money(c.facts.amount)}</strong> · {c.facts.category} · {formatDate(c.facts.start)} – {formatDate(c.facts.end)}</p>{:else if c.tool==='forecast'}<p>{L('Safe to spend','Aman dibelanjakan')}: {money(c.facts.safeToSpend)} · {L('Minimum cash','Kas minimum')}: {money(c.facts.minimumBalance)}</p>{:else if Array.isArray(c.facts)}<ul>{#each c.facts as f}<li>{f.name??f.number}{c.tool==='receivables'?` · ${f.number}`:''} · {money(f.outstanding??f.amount??f.allocated)}{f.dueDate||f.date?` · ${formatDate(f.dueDate??f.date)}`:''}</li>{/each}</ul>{/if}{/if}{#if !privacy.hidden&&c.citations.length}<Disclosure>{#snippet title()}{L('Source records','Catatan sumber')}{/snippet}<ul>{#each c.citations as citation}<li>{citation.label??L('Source record','Catatan sumber')}{citation.date?` · ${formatDate(citation.date)}`:''}{citation.amount?` · ${money(citation.amount)}`:''}</li>{/each}</ul></Disclosure>{/if}<p class="muted">{c.citations.length} {L('source records','catatan sumber')}</p><Button variant="link" href={c.tool==='receivables'?'/invoices':c.tool==='goals'?'/goals':c.tool==='bills'?'/bills':'/transactions'}>{L('Review source records','Tinjau catatan sumber')}</Button></article>{/each}</div><form onsubmit={e=>{e.preventDefault();void ask();}}><label>{L('Your question','Pertanyaanmu')}<Textarea bind:value={question} maxlength={2000} required oninput={()=>chatKey=cryptoSafe()}/></label><Button type="submit" disabled={busy||!externalEnabled}>{L('Ask Capy','Tanya Capy')}</Button></form>
 {:else if tab==='entry'}<p class="muted">{providerName}</p><h3>{L('Say it simply, then review','Katakan dengan sederhana, lalu tinjau')}</h3><p class="muted">{L('For example: “Lunch 45k today from Cash, category Food.” The text goes to the configured provider for extraction. Nothing is saved as a transaction until you review and confirm.','Contoh: “Makan 45k hari ini dari Kas, kategori Makanan.” Teks dikirim ke penyedia yang dikonfigurasi untuk ekstraksi. Transaksi baru disimpan setelah kamu meninjau dan mengonfirmasi.')}</p><label>{L('Transaction description or transcript','Deskripsi transaksi atau transkrip')}<Textarea bind:value={entryText} maxlength={2000} oninput={()=>entryKey=cryptoSafe()}/></label><div class="actions"><Button onclick={parseEntry} disabled={busy||!externalEnabled||!entryText.trim()}>{L('Create review draft','Buat draf tinjauan')}</Button>{#if recording}<Button variant="outline" onclick={()=>stopRecording(false)}>{L('Stop & transcribe','Hentikan & transkrip')}</Button><Button variant="ghost" onclick={()=>stopRecording(true)}>{L('Cancel recording','Batalkan rekaman')}</Button>{:else}<Button variant="outline" onclick={record} disabled={busy||pendingRecording||!voiceEnabled||!externalEnabled}>{L('Record voice','Rekam suara')}</Button>{/if}</div><p class="muted">{recording?L('Recording… stops after 30 seconds.','Merekam… berhenti setelah 30 detik.'):L('Voice requires separate consent. Up to 30 seconds / 2 MB. Audio is sent to the configured provider, kept transiently here, and discarded after transcription. Provider retention depends on its terms and privacy controls.','Suara memerlukan izin terpisah. Maksimal 30 detik / 2 MB. Audio dikirim ke penyedia yang dikonfigurasi, diproses sementara di sini, lalu dibuang setelah transkripsi. Penyimpanan oleh penyedia mengikuti ketentuan dan pengaturan privasinya.')}</p>
 {#if draft}<form onsubmit={e=>{e.preventDefault();void confirmEntry();}}><h4>{L('Review before saving','Tinjau sebelum menyimpan')}</h4><p class="muted">{L('Complete any missing fields. Choose the account and category yourself if they are unclear.','Lengkapi kolom yang belum terisi. Pilih sendiri akun dan kategori jika belum jelas.')}</p><div class="form-grid"><label>{L('Type','Jenis')}<ChoiceSelect bind:value={draft.fields.type} items={[{value:'',label:L('Select','Pilih')},{value:'expense',label:L('Expense','Pengeluaran')},{value:'income',label:L('Income','Pemasukan')}]} required/></label><label>{L('Amount','Jumlah')}<AmountInput bind:value={draft.fields.amount} currency={draft.fields.currency} required/></label><label>{L('Date','Tanggal')}<DatePicker bind:value={draft.fields.date} required/></label><label>{L('Account','Akun')}<ChoiceSelect bind:value={draft.fields.accountId} onValueChange={(id)=>{draft.fields.currency=draft.accounts.find((a:any)=>a.id===id)?.currency??draft.fields.currency;}} items={[{value:'',label:L('Select','Pilih')},...draft.accounts.map((a:any)=>({value:a.id,label:`${a.name} (${a.currency})`}))]} required/></label><label>{L('Category','Kategori')}<ChoiceSelect bind:value={draft.fields.categoryId} items={[{value:'',label:L('Select','Pilih')},...draft.categories.filter((c:any)=>c.type===draft.fields.type).map((c:any)=>({value:c.id,label:c.name}))]} required/></label><label>{L('Merchant','Penjual')}<Input bind:value={draft.fields.merchant} maxlength={200}/></label></div><div class="actions"><Button type="submit" disabled={busy}>{L('Confirm & save transaction','Konfirmasi & simpan transaksi')}</Button><Button variant="ghost" onclick={()=>draft=null}>{L('Discard draft','Buang draf')}</Button></div></form>{/if}
 {:else if tab==='summaries'}<div class="section-heading"><h3>{L('A calm money check-in','Ringkasan uang yang tenang')}</h3><Button variant="outline" onclick={load} disabled={busy}>{L('Load check-ins','Muat ringkasan')}</Button></div>{#if summary}<p>{L('Last complete week','Minggu penuh terakhir')}: {formatDate(summary.preview.start)} – {formatDate(summary.preview.end)}</p><p>{L(`You recorded ${money(summary.preview.income)} in income and ${money(summary.preview.expenses)} in expenses during this period.`,`Kamu mencatat pemasukan ${money(summary.preview.income)} dan pengeluaran ${money(summary.preview.expenses)} pada periode ini.`)}</p><p class="muted">{L('Expense change from the previous period','Perubahan pengeluaran dari periode sebelumnya')}: {money(summary.preview.expenseChange)}</p><div class="metrics"><div><small>{L('Income','Pemasukan')}</small><strong>{money(summary.preview.income)}</strong></div><div><small>{L('Expenses','Pengeluaran')}</small><strong>{money(summary.preview.expenses)}</strong></div></div><Disclosure>{#snippet title()}{L('What this check-in includes','Isi ringkasan ini')}{/snippet}<p>{L('Safe to spend today','Aman dibelanjakan hari ini')}: {money(summary.preview.safeToSpend)}</p><h4>{L('Upcoming obligations','Kewajiban mendatang')}</h4>{#if summary.preview.upcomingBills.length}<ul>{#each summary.preview.upcomingBills as bill}<li>{bill.description} · {formatDate(bill.date)} · {money(bill.amount)}</li>{/each}</ul>{:else}<p>{L('No upcoming bills in the permitted forecast sources.','Tidak ada tagihan mendatang pada sumber proyeksi yang diizinkan.')}</p>{/if}<h4>{L('Goal progress','Progres tujuan')}</h4><ul>{#each summary.preview.goals as goal}<li>{goal.name} · {money(goal.allocated)} / {money(goal.target)}{goal.coaching.weeklyTarget?` · ${L('Weekly target','Target mingguan')}: ${money(goal.coaching.weeklyTarget)}`:''}</li>{/each}</ul>{#if summary.preview.receivables.length}<h4>{L('Business invoices','Faktur bisnis')}</h4><ul>{#each summary.preview.receivables.filter((i:any)=>i.hasUnpaid) as invoice}<li>{invoice.number} · {formatDate(invoice.dueDate)} · {money(invoice.outstanding)}</li>{/each}</ul>{/if}<p class="muted">{summary.preview.evidence.length} {L('cited transaction records; review them in Transactions.','catatan transaksi sumber; tinjau di Transaksi.')}</p><Button variant="link" href="/transactions">{L('Review source records','Tinjau catatan sumber')}</Button></Disclosure><Disclosure>{#snippet title()}{L('Check-in preferences','Preferensi ringkasan')}{/snippet}<label class="check"><Checkbox bind:checked={scheduleEnabled}/>{L('Receive summaries','Terima ringkasan')}</label><div class="form-grid"><label>{L('Summary cadence','Jadwal ringkasan')}<ChoiceSelect bind:value={cadence} items={[{value:'weekly',label:L('Weekly','Mingguan')},{value:'monthly',label:L('Monthly','Bulanan')}]}/></label><label>{L('Proactive reminders','Pengingat proaktif')}<ChoiceSelect bind:value={nudges} items={[{value:'off',label:L('Off','Nonaktif')},{value:'daily',label:L('Daily','Harian')},{value:'weekly',label:L('Weekly','Mingguan')}]}/></label><label>{L('Send time (workspace timezone)','Waktu kirim (zona waktu workspace)')}<Input type="time" bind:value={sendTime}/></label><label>{L('Quiet hours start','Mulai jam tenang')}<Input type="time" bind:value={quietStart}/></label><label>{L('Quiet hours end','Akhir jam tenang')}<Input type="time" bind:value={quietEnd}/></label></div><label class="check"><Checkbox bind:checked={email}/>{L('Also email period income and expense totals','Kirim juga total pemasukan dan pengeluaran via email')}</label><p class="muted">{L('Two negative ratings for different suggestions of the same type pause optional nudges for 14 days. Helpful feedback restores your chosen frequency. Due-date alerts keep their own settings.','Dua penilaian negatif untuk saran berbeda dengan jenis yang sama menjeda pengingat opsional selama 14 hari. Penilaian membantu memulihkan frekuensi pilihanmu. Peringatan jatuh tempo tetap mengikuti pengaturannya sendiri.')}</p><Button onclick={saveSchedule} disabled={busy}>{L('Save preferences','Simpan preferensi')}</Button></Disclosure><div class="item-list">{#each summary.items as s}<article><h4>{formatDate(s.period_start)} – {formatDate(s.period_end)}</h4><p>{L('Income','Pemasukan')}: {money(s.metrics.income)} · {L('Expenses','Pengeluaran')}: {money(s.metrics.expenses)}</p><FeedbackControls value={s.feedback} disabled={busy} onsubmit={(action)=>feedback('summary',s,action)}/></article>{/each}</div>{/if}
 {/if}
 <p class="disclaimer">{L('Helpful information, not professional financial, tax or legal advice. You always review and confirm changes.','Informasi pendukung, bukan nasihat keuangan, pajak, atau hukum profesional. Kamu selalu meninjau dan mengonfirmasi perubahan.')}</p>
</Card.Content></Card.Root>
<style>
 .tabs,.actions,.section-heading{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.tabs{margin-bottom:24px}.section-heading{justify-content:space-between}form{display:grid;gap:16px;margin:16px 0}.form-grid,.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:16px}label{display:grid;gap:8px;font-size:14px;font-weight:600}.check{display:flex;align-items:center;gap:12px;min-height:44px}.item-list{display:grid;gap:16px;margin:16px 0}.item-list article{padding:16px;border:2px solid var(--border);border-radius:var(--radius-card,20px);background:var(--card)}h3{font:500 20px var(--font-heading);margin:16px 0}h4{font:500 17px var(--font-heading);margin:16px 0 8px}h5{font:500 16px var(--font-heading);margin:0 0 8px}p{margin:8px 0;line-height:1.6}.muted,.disclaimer{font-size:13px;color:var(--muted-foreground)}.disclaimer{margin-top:24px}.metrics>div{display:grid;gap:8px;padding:16px;border-radius:var(--radius-card,20px);background:var(--muted)}.metrics strong{font-size:22px;font-variant-numeric:tabular-nums}.error{color:var(--text-coral)}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:12px;text-align:left;border-bottom:1px solid var(--border);white-space:nowrap}tbody th{font-weight:600}td{font-variant-numeric:tabular-nums}ul{padding-left:24px}:global(.v2-panel){min-width:0}
</style>
